DECLARE
  v_user uuid := auth.uid();
  v_order record;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_order_id');
  END IF;

  SELECT * INTO v_order
  FROM app.marketplace_orders o
  WHERE o.id = p_order_id
    AND o.student_id = v_user
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'order', to_jsonb(v_order),
    'items', (
      SELECT COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'product_id', i.product_id,
            'quantity', i.quantity,
            'unit_price', i.unit_price,
            'currency', i.currency,
            'title', l.title
          )
          ORDER BY i.id
        ),
        '[]'::jsonb
      )
      FROM app.marketplace_order_items i
      JOIN app.marketplace_listings l ON l.id = i.product_id
      WHERE i.order_id = p_order_id
    )
  );
END;

DECLARE
  v_user uuid := auth.uid();
  v_role text;
  v_order record;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;
  IF p_order_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_order_id');
  END IF;

  v_role := public.app_get_current_role();
  IF v_role <> 'merchant' THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_merchant');
  END IF;

  SELECT * INTO v_order
  FROM app.marketplace_orders o
  WHERE o.id = p_order_id
    AND o.merchant_id = v_user
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'order', to_jsonb(v_order),
    'items', (
      SELECT COALESCE(
        jsonb_agg(
          jsonb_build_object(
            'id', i.id,
            'product_id', i.product_id,
            'quantity', i.quantity,
            'unit_price', i.unit_price,
            'currency', i.currency,
            'title', l.title
          )
          ORDER BY i.id
        ),
        '[]'::jsonb
      )
      FROM app.marketplace_order_items i
      JOIN app.marketplace_listings l ON l.id = i.product_id
      WHERE i.order_id = p_order_id
    )
  );
END;

DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_merchant_id UUID;
    v_result JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'merchant' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_merchant');
    END IF;

    SELECT id
    INTO v_merchant_id
    FROM app.marketplace_merchants
    WHERE owner_user_id = v_user_id
    ORDER BY created_at
    LIMIT 1;

    IF v_merchant_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'merchant_not_found');
    END IF;

    SELECT COALESCE(
        JSONB_AGG(
            JSONB_BUILD_OBJECT(
                'order_id', o.id,
                'status', o.status,
                'total_amount', o.total_amount,
                'currency', o.currency,
                'delivery_mode', o.delivery_mode,
                'shipping_address', o.shipping_address,
                'student_notes', o.student_notes,
                'created_at', o.created_at,
                'student_id', o.student_id,
                'student_full_name', s.full_name,
                'items', (
                    SELECT COALESCE(
                        JSONB_AGG(
                            JSONB_BUILD_OBJECT(
                                'product_id', i.product_id,
                                'quantity', i.quantity,
                                'unit_price', i.unit_price,
                                'currency', i.currency,
                                'product_title', p2.title,
                                'product_main_image_url', p2.main_image_url
                            )
                        ),
                        '[]'::JSONB
                    )
                    FROM app.marketplace_order_items i
                    JOIN app.marketplace_products p2 ON p2.id = i.product_id
                    WHERE i.order_id = o.id
                )
            )
            ORDER BY o.created_at DESC
        ),
        '[]'::JSONB
    )
    INTO v_result
    FROM app.marketplace_orders o
    LEFT JOIN app.students s ON s.id = o.student_id
    WHERE o.merchant_id = v_merchant_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'orders', v_result);
END;

DECLARE
    v_user_id UUID := auth.uid();
    v_student_id UUID;
    v_product RECORD;
    v_order_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    -- Vérifier que le profil étudiant existe
    SELECT s.id INTO v_student_id
    FROM app.students s
    WHERE s.id = v_user_id;

    IF v_student_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'student_profile_not_found');
    END IF;

    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_quantity');
    END IF;

    SELECT p.*, m.id AS merchant_id
    INTO v_product
    FROM app.marketplace_products p
    JOIN app.marketplace_merchants m ON m.id = p.merchant_id
    WHERE p.id = p_product_id
      AND p.status = 'published'
      AND m.status = 'approved'
      AND m.is_active = TRUE;

    IF v_product.id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'product_not_available');
    END IF;

    IF v_product.price IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'product_price_not_defined');
    END IF;

    INSERT INTO app.marketplace_orders (
        student_id,
        merchant_id,
        status,
        total_amount,
        currency,
        delivery_mode,
        shipping_address,
        student_notes
    )
    VALUES (
        v_student_id,
        v_product.merchant_id,
        'pending',
        v_product.price * p_quantity,
        v_product.currency,
        p_delivery_mode,
        p_shipping_address,
        p_student_notes
    )
    RETURNING id INTO v_order_id;

    INSERT INTO app.marketplace_order_items (
        order_id,
        product_id,
        quantity,
        unit_price,
        currency
    )
    VALUES (
        v_order_id,
        v_product.id,
        p_quantity,
        v_product.price,
        v_product.currency
    );

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'order_id', v_order_id
    );
END;
